import{_ as n,c as e,o as p,b0 as l}from"./chunks/framework.Becqh7-x.js";const i="/linux-dev-docs/assets/image-20230716170503614.Dct7c2t6.png",r="/linux-dev-docs/assets/image-20241107075112786.BqhLHMko.png",t="/linux-dev-docs/assets/image-20260114150408545.BMyrLJE_.png",c="/linux-dev-docs/assets/image-20260114150508109.BCzstx_p.png",b="/linux-dev-docs/assets/image-20260114150637567.DHSqqBev.png",d="/linux-dev-docs/assets/image-20260114150716028.DqTjtZLv.png",o="/linux-dev-docs/assets/image-20260114150819958.CeaMsSWc.png",u="/linux-dev-docs/assets/image-20260114151104238.r8t5ov8I.png",h="/linux-dev-docs/assets/image-20260114151302724.BHAbAOfN.png",m="/linux-dev-docs/assets/image-20260114151337972.Dpg9gpvu.png",_="/linux-dev-docs/assets/image-20260114151411133.k7OmoU8m.png",g="/linux-dev-docs/assets/image-20260114151610875.C2Eb7uaz.png",C="/linux-dev-docs/assets/image-20260114151543021.CcVOwvB4.png",k="/linux-dev-docs/assets/image-20260114151513874.PaSehLKT.png",I="/linux-dev-docs/assets/image-20260114152041922.DMUQjIEA.png",O="/linux-dev-docs/assets/image-20260114152109674.CfNdzFee.png",a="/linux-dev-docs/assets/image-20260114152143146.BcduMxpE.png",P="/linux-dev-docs/assets/image-20260114152320222.BJzFfyKx.png",v="/linux-dev-docs/assets/image-20260114152415634.DXK50Y8J.png",G="/linux-dev-docs/assets/image-20260114152618584.DU8nphGK.png",F="/linux-dev-docs/assets/image-20241108000446239.CxKDAxhs.png",x="/linux-dev-docs/assets/image-20241108000520398.e9Djmd3x.png",f="/linux-dev-docs/assets/image-20241108000549113.DPK5Zddv.png",y="/linux-dev-docs/assets/image-20241108000654980.BE4fRXPi.png",B=JSON.parse('{"title":"LV050-汇编点亮LED","description":null,"frontmatter":{"title":"LV050-汇编点亮LED","date":"2026-01-14T13:56:27.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/bare/gpio/126d2ce7fa4b284676ba0add","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-14T13:56:27.644Z","fulluuid":"676ba0add9f34e77ab3d6c27369bf880","useduuid":"676ba0add"}},"headers":[],"relativePath":"sdoc/bare/gpio/126d2ce7fa4b284676ba0add.md","filePath":"sdoc/25-裸机开发/10-GPIO控制/LV050-汇编点亮LED.md","lastUpdated":1768604092000}'),M={name:"sdoc/bare/gpio/126d2ce7fa4b284676ba0add.md"};function X(D,s,E,q,R,L){return p(),e("div",null,[...s[0]||(s[0]=[l('<h1 id="lv050-汇编点亮led" tabindex="-1">LV050-汇编点亮LED <a class="header-anchor" href="#lv050-汇编点亮led" aria-label="Permalink to &quot;LV050-汇编点亮LED&quot;">​</a></h1><h2 id="一、硬件原理图" tabindex="-1">一、硬件原理图 <a class="header-anchor" href="#一、硬件原理图" aria-label="Permalink to &quot;一、硬件原理图&quot;">​</a></h2><p>我们先看底板原理图（&quot;阿尔法Linux开发板（A盘）-基础资料/02、开发板原理图/IMX6ULL_ALPHA_V2.2(底板原理图).pdf&quot;</p><img src="'+i+'" alt="image-20230716170503614" style="zoom:50%;"><p>可以看到LED0 接到了 GPIO_3 上， 这个GPIO_3是哪个引脚？感觉这里标的有问题，我们搜索一下，会发现这里接在一个BTB连接器母座上，所以我们再去搜一些核心板原理图 &quot;阿尔法Linux开发板（A盘）-基础资料/02、开发板原理图/IMX6ULL_CORE_V1.6(核心板原理图).pdf&quot;：</p><img src="'+r+`" alt="image-20241107075112786"><p>就会发现GPIO_3 就是 GPIO1_IO03，根据底板原理图，当 GPIO1_IO03输出低电平(0)的时候发光二极管 LED0 就会导通点亮，GPIO1_IO03 输出高电平(1)的时候发光二极管 LED0 不会导通，因此 LED0 也就不会点亮。所以 LED0 的亮灭取决于 GPIO1_IO03的输出电平，输出 0 就亮，输出 1 就灭。</p><h2 id="二、怎么操作gpio" tabindex="-1">二、怎么操作GPIO？ <a class="header-anchor" href="#二、怎么操作gpio" aria-label="Permalink to &quot;二、怎么操作GPIO？&quot;">​</a></h2><p>主要是配置三大控制模块：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CCM    : Clock Controller Module      时钟控制模块</span></span>
<span class="line"><span>IOMUXC : IOMUX Controller             IO 复用控制器</span></span>
<span class="line"><span>GPIO   : General-purpose input/output 通用的输入输出口</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_1-基本步骤" tabindex="-1">1. 基本步骤 <a class="header-anchor" href="#_1-基本步骤" aria-label="Permalink to &quot;1. 基本步骤&quot;">​</a></h3><ul><li>（1）使能 GPIO1 时钟</li></ul><p>GPIO1 的时钟由 CCM_CCGR1 的 bit27 和 bit26 这两个位控制，将这两个位都设置位 11 即可。</p><ul><li>（2）设置 GPIO1_IO03 的复用功能</li></ul><p>找到 GPIO1_IO03 的复用寄存器“IOMUXC_SW_MUX_CTL_PAD_GPIO1_IO03”的地址为0X020E0068，然后设置此寄存器，将 GPIO1_IO03 这个 IO 复用为 GPIO 功能，也就是 ALT5。</p><ul><li>（3）配置 GPIO1_IO03功能和参数</li></ul><p>找到 GPIO1_IO03 的配置寄存器“IOMUXC_SW_PAD_CTL_PAD_GPIO1_IO03”的地址为0X020E02F4，根据实际使用情况，配置此寄存器。</p><ul><li>（4）设置GPIO</li></ul><p>将 GPIO1_IO03 复用为了 GPIO 功能，我们还需要配置 GPIO。 找到 GPIO3 对应的 GPIO 组寄存器地址，在《i.MX 6ULL Applications Processor Reference Manual》的 28.5 GPIO Memory Map/Register Definition ：</p><p><img src="`+t+`" alt="image-20260114150408545"></p><p>GPIO1_IO03 是作为输出功能的，因此 GPIO1_GDIR 的 bit3 要设置为 1，表示输出。</p><ul><li>（5）控制 GPIO 的输出电平</li></ul><p>向 GPIO1_DR 寄存器的 bit3 写入 0 即可控制 GPIO1_IO03 输出低电平，打开 LED，向 bit3 写入 1 可控制 GPIO1_IO03 输出高电平，关闭 LED。</p><h3 id="_2-gpio寄存器操作" tabindex="-1">2. GPIO寄存器操作 <a class="header-anchor" href="#_2-gpio寄存器操作" aria-label="Permalink to &quot;2. GPIO寄存器操作&quot;">​</a></h3><p>GPIO 寄存器的 2 种操作方法，原则是不能影响到其他位 。</p><p>（1）读出、修改对应位、写入</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* 设置bit n */</span></span>
<span class="line"><span>val = data_reg;</span></span>
<span class="line"><span>val = val | (1 &lt;&lt; n);</span></span>
<span class="line"><span>data_reg = val;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/* 清除 bit n */</span></span>
<span class="line"><span>val = data_reg;</span></span>
<span class="line"><span>val = val &amp; ~(1 &lt;&lt; n);</span></span>
<span class="line"><span>data_reg = val;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>（2）set-and-clear protocol</p><p>set_reg, clr_reg, data_reg 三个寄存器对应的是同一个物理寄存器,</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* 要设置 bit n */</span></span>
<span class="line"><span>set_reg = (1&lt;&lt;n);</span></span>
<span class="line"><span>/* 要清除 bit n */</span></span>
<span class="line"><span>clr_reg = (1&lt;&lt;n);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这种方式会影响到其他的位，还是上面的方式更好一些，只针对某一位进行操作。</p><h2 id="三、代码编写与分析" tabindex="-1">三、代码编写与分析 <a class="header-anchor" href="#三、代码编写与分析" aria-label="Permalink to &quot;三、代码编写与分析&quot;">​</a></h2><h3 id="_1-led-s完整内容" tabindex="-1">1. led.s完整内容 <a class="header-anchor" href="#_1-led-s完整内容" aria-label="Permalink to &quot;1. led.s完整内容&quot;">​</a></h3><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.global _start  /* 全局标号 */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/*</span></span>
<span class="line"><span> * 描述：	_start函数，程序从此函数开始执行此函数完成时钟使能、</span></span>
<span class="line"><span> *		  GPIO初始化、最终控制GPIO输出低电平来点亮LED灯。</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>_start:</span></span>
<span class="line"><span>	/* 例程代码 */</span></span>
<span class="line"><span>	/* 1、使能所有时钟 */</span></span>
<span class="line"><span>	ldr r0, =0X020C4068 	/* CCGR0 */</span></span>
<span class="line"><span>	ldr r1, =0XFFFFFFFF  </span></span>
<span class="line"><span>	str r1, [r0]		</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	ldr r0, =0X020C406C  	/* CCGR1 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	ldr r0, =0X020C4070  	/* CCGR2 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	ldr r0, =0X020C4074  	/* CCGR3 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	ldr r0, =0X020C4078  	/* CCGR4 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	ldr r0, =0X020C407C  	/* CCGR5 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	ldr r0, =0X020C4080  	/* CCGR6 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	/* 2、设置GPIO1_IO03复用为GPIO1_IO03 */</span></span>
<span class="line"><span>	ldr r0, =0X020E0068	/* 将寄存器SW_MUX_GPIO1_IO03_BASE加载到r0中 */</span></span>
<span class="line"><span>	ldr r1, =0X5		/* 设置寄存器SW_MUX_GPIO1_IO03_BASE的MUX_MODE为5 */</span></span>
<span class="line"><span>	str r1,[r0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	/* 3、配置GPIO1_IO03的IO属性	</span></span>
<span class="line"><span>	 * bit 16:0 HYS关闭</span></span>
<span class="line"><span>	 * bit [15:14]: 00 默认下拉</span></span>
<span class="line"><span>     * bit [13]: 0 kepper功能</span></span>
<span class="line"><span>     * bit [12]: 1 pull/keeper使能</span></span>
<span class="line"><span>     * bit [11]: 0 关闭开路输出</span></span>
<span class="line"><span>     * bit [7:6]: 10 速度100Mhz</span></span>
<span class="line"><span>     * bit [5:3]: 110 R0/6驱动能力</span></span>
<span class="line"><span>     * bit [0]: 0 低转换率</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    ldr r0, =0X020E02F4	/*寄存器SW_PAD_GPIO1_IO03_BASE */</span></span>
<span class="line"><span>    ldr r1, =0X10B0</span></span>
<span class="line"><span>    str r1,[r0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	/* 4、设置GPIO1_IO03为输出 */</span></span>
<span class="line"><span>    ldr r0, =0X0209C004	/*寄存器GPIO1_GDIR */</span></span>
<span class="line"><span>    ldr r1, =0X0000008		</span></span>
<span class="line"><span>    str r1,[r0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	/* 5、打开LED0</span></span>
<span class="line"><span>	 * 设置GPIO1_IO03输出低电平</span></span>
<span class="line"><span>	 */</span></span>
<span class="line"><span>    ldr r0, =0X0209C000	/*寄存器GPIO1_DR */</span></span>
<span class="line"><span>    ldr r1, =0		</span></span>
<span class="line"><span>    str r1,[r0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/*</span></span>
<span class="line"><span> * 描述：	loop死循环</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>loop:</span></span>
<span class="line"><span>	b loop</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br></div></div><h3 id="_2-详细分析" tabindex="-1">2. 详细分析 <a class="header-anchor" href="#_2-详细分析" aria-label="Permalink to &quot;2. 详细分析&quot;">​</a></h3><h4 id="_2-1-全局标号" tabindex="-1">2.1 全局标号 <a class="header-anchor" href="#_2-1-全局标号" aria-label="Permalink to &quot;2.1 全局标号&quot;">​</a></h4><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.global _start  /* 全局标号 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>定义了一个全局标号_start，代码就是从_start 这个标号开始顺序往下执行的。</p><h4 id="_2-2-使能时钟" tabindex="-1">2.2 使能时钟 <a class="header-anchor" href="#_2-2-使能时钟" aria-label="Permalink to &quot;2.2 使能时钟&quot;">​</a></h4><h5 id="_2-2-1-gpio时钟用哪个寄存器" tabindex="-1">2.2.1 GPIO时钟用哪个寄存器？ <a class="header-anchor" href="#_2-2-1-gpio时钟用哪个寄存器" aria-label="Permalink to &quot;2.2.1 GPIO时钟用哪个寄存器？&quot;">​</a></h5><p>我们翻一下《i.MX 6ULL Applications Processor Reference Manual》18.4 System Clocks 这一节，我们看一下Table 18-3. System Clocks, Gating, and Override (continued) 这个表格，具体GPIO应该是在 P635：</p><p><img src="`+c+'" alt="image-20260114150508109"></p><p>可以看到这里每一组的GPIO时钟是由CCM_CCGRx寄存器来控制，我们使用的是GPIO1所以对应的应该是CCM_CCGR1[CG13]，我们看一下这个是什么，我们可以全局搜索CCGR1，就可以找到这个寄存器，它其实位于参考手册18.6.24 CCM Clock Gating Register 1 (CCM_CCGR1)这一节，大概在P 700：</p><p><img src="'+b+'" alt="image-20260114150637567"></p><p>可以看到，这个是个32位寄存器，每两位控制一个时钟，我们的GPIO1就位于27-26，就是CG13，可以看到这个前面的表格是对应的，那么这两位怎么配置表示开启时钟？我们可以再在18.6.23 CCM Clock Gating Register 0 (CCM_CCGR0) 这一节找到：</p><p><img src="'+d+'" alt="image-20260114150716028"></p><table tabindex="0"><thead><tr><th>CGR</th><th>时钟状态描述</th></tr></thead><tbody><tr><td>00</td><td>时钟在所有模式下都是关闭的</td></tr><tr><td>01</td><td>时钟在运行模式下为开，但在等待和停止模式下为关</td></tr><tr><td>10</td><td>保留</td></tr><tr><td>11</td><td>除停止模式外，时钟一直开启</td></tr></tbody></table><p>目前我们可以全部设置为1，我们看上面的寄存器描述中，有一个reset，这个表示默认状态下的复位后的值，发现它其实默认就是11，也就是说时钟默认是打开的，但是为了规范，我们还是需要操作一遍。</p><h5 id="_2-2-2-寄存器地址" tabindex="-1">2.2.2 寄存器地址？ <a class="header-anchor" href="#_2-2-2-寄存器地址" aria-label="Permalink to &quot;2.2.2 寄存器地址？&quot;">​</a></h5><p>我们知道要用到哪个寄存器，并且也知道了要配什么值，那么怎么操作？我们需要找到这个寄存器的地址，然后写值进去，地址怎么找？其实刚才找寄存器的时候有的：</p><p><img src="'+o+'" alt="image-20260114150819958"></p><p>这里就写了，基地址是20C_4000h，偏移地址是6Ch，加到一起就是绝对地址 20C_406Ch。其实参考手册还有一个地方可以看到，就是这里：18.6 CCM Memory Map/Register Definition：</p><p><img src="'+u+`" alt="image-20260114151104238"></p><p>从这里可以直接看到寄存器的绝对地址和默认值。</p><h5 id="_2-2-3-代码分析" tabindex="-1">2.2.3 代码分析 <a class="header-anchor" href="#_2-2-3-代码分析" aria-label="Permalink to &quot;2.2.3 代码分析&quot;">​</a></h5><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>	ldr r0, =0X020C4068 	/* CCGR0 */</span></span>
<span class="line"><span>	ldr r1, =0XFFFFFFFF  </span></span>
<span class="line"><span>	str r1, [r0]		</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	ldr r0, =0X020C406C  	/* CCGR1 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	ldr r0, =0X020C4070  	/* CCGR2 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	ldr r0, =0X020C4074  	/* CCGR3 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	ldr r0, =0X020C4078  	/* CCGR4 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	ldr r0, =0X020C407C  	/* CCGR5 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	ldr r0, =0X020C4080  	/* CCGR6 */</span></span>
<span class="line"><span>	str r1, [r0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p>第 1 行：使用 ldr 指令向寄存器 r0 写入 0X020C4068，也就是 r0=0X020C4068，这个是CCM_CCGR0 寄存器的地址。</p><p>第 2 行：使用 ldr 指令向寄存器 r1 写入 0XFFFFFFFF，也就是 r1=0XFFFFFFFF。因为我们:要开启所有的外设时钟，因此 CCM_CCGR0 ~ CCM_CCGR6 所有寄存器的 32 位都要置 1，也就是写入 0XFFFFFFFF。</p><p>第 3 行：使用 str 将 r1 中的值写入到 r0 所保存的地址中去，也就是给 0X020C4068 这个地址写入 0XFFFFFFFF，相当于CCM_CCGR0 = 0XFFFFFFFF，就是打开 CCM_CCGR0 寄存器所控制的所有外设时钟。</p><p>第 5 ~21 行都是向 CCM_CCGRX(X=1~6)寄存器写入 0XFFFFFFFF。这样我就通过汇编代码使能了 I.MX6U 的所有外设时钟。</p><h4 id="_2-3-设置io复用功能" tabindex="-1">2.3 设置IO复用功能 <a class="header-anchor" href="#_2-3-设置io复用功能" aria-label="Permalink to &quot;2.3 设置IO复用功能&quot;">​</a></h4><h5 id="_2-3-1-用哪个寄存器" tabindex="-1">2.3.1 用哪个寄存器？ <a class="header-anchor" href="#_2-3-1-用哪个寄存器" aria-label="Permalink to &quot;2.3.1 用哪个寄存器？&quot;">​</a></h5><p>前面我们知道IO有多种复用功能，这里我们需要将此引脚作为输出功能，就是普通的GPIO，用哪个寄存器？我们前面有说过，设置复用模式我们要找包含MUX_CTL关键词的配置寄存器，我们直接搜GPIO1_IO03，可以找到参考手册中这个32.6.10 SW_MUX_CTL_PAD_GPIO1_IO03 SW MUX Control Register (IOMUXC_SW_MUX_CTL_PAD_GPIO1_IO03) 这一节的这个寄存器：</p><p><img src="`+h+'" alt="image-20260114151302724"></p><p>可以看到我们需要配置这个寄存器的[3:0]为0101，这个时候这个引脚就是GPIO1_IO03功能。</p><h5 id="_2-3-2-寄存器地址" tabindex="-1">2.3.2 寄存器地址？ <a class="header-anchor" href="#_2-3-2-寄存器地址" aria-label="Permalink to &quot;2.3.2 寄存器地址？&quot;">​</a></h5><p>（1）参考手册32.6.10 SW_MUX_CTL_PAD_GPIO1_IO03 SW MUX ControlRegister (IOMUXC_SW_MUX_CTL_PAD_GPIO1_IO03)</p><p><img src="'+m+'" alt="image-20260114151337972"></p><p>（2）参考手册32.6 IOMUXC Memory Map/Register Definition</p><p><img src="'+_+`" alt="image-20260114151411133"></p><h5 id="_2-3-3-代码分析" tabindex="-1">2.3.3 代码分析 <a class="header-anchor" href="#_2-3-3-代码分析" aria-label="Permalink to &quot;2.3.3 代码分析&quot;">​</a></h5><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>	ldr r0, =0X020E0068	/* 将寄存器SW_MUX_GPIO1_IO03_BASE加载到r0中 */</span></span>
<span class="line"><span>	ldr r1, =0X5		/* 设置寄存器SW_MUX_GPIO1_IO03_BASE的MUX_MODE为5 */</span></span>
<span class="line"><span>	str r1,[r0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>第 1~3 行：是设置GPIO1_IO03的复用功能， GPIO1_IO03的复用寄存器地址为0X020E0068，寄 存 器 IOMUXC_SW_MUX_CTL_PAD_GPIO1_IO03 的 MUX_MODE 设 置 为 5 就 是 将GPIO1_IO03 设置为 GPIO。</p><h4 id="_2-4-设置io属性" tabindex="-1">2.4 设置IO属性 <a class="header-anchor" href="#_2-4-设置io属性" aria-label="Permalink to &quot;2.4 设置IO属性&quot;">​</a></h4><h5 id="_2-4-1-用哪个寄存器" tabindex="-1">2.4.1 用哪个寄存器？ <a class="header-anchor" href="#_2-4-1-用哪个寄存器" aria-label="Permalink to &quot;2.4.1 用哪个寄存器？&quot;">​</a></h5><p>设置IO属性的时候就是配置一下上下来、压摆率等相关参数，前面的复用功能配置集训期命名为SW_MUX_CTL_PAD_GPIO1_IO03，那么这里IO属性配置寄存器大概应该就是SW_PAD_CTL_PAD_GPIO1_IO03，我们直接全局搜索GPIO1_IO03，会在参考手册32.6.156 SW_PAD_CTL_PAD_GPIO1_IO03 SW PAD Control Register (IOMUXC_SW_PAD_CTL_PAD_GPIO1_IO03) 中搜到这个寄存器：</p><p><img src="`+g+'" alt="image-20260114151610875"></p><p>这里面就是配置IO属性的地方，这里详细的可以直接去看手册。</p><h5 id="_2-4-2-寄存器地址" tabindex="-1">2.4.2 寄存器地址？ <a class="header-anchor" href="#_2-4-2-寄存器地址" aria-label="Permalink to &quot;2.4.2 寄存器地址？&quot;">​</a></h5><p>还是那两个地方：</p><p>（1）32.6.156 SW_PAD_CTL_PAD_GPIO1_IO03 SW PAD Control Register (IOMUXC_SW_PAD_CTL_PAD_GPIO1_IO03)</p><p><img src="'+C+'" alt="image-20260114151543021"></p><p>（2）32.6 IOMUXC Memory Map/Register Definition</p><p><img src="'+k+`" alt="image-20260114151513874"></p><h5 id="_2-4-3-代码分析" tabindex="-1">2.4.3 代码分析 <a class="header-anchor" href="#_2-4-3-代码分析" aria-label="Permalink to &quot;2.4.3 代码分析&quot;">​</a></h5><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>	/**</span></span>
<span class="line"><span>	 * bit 16:0 HYS关闭</span></span>
<span class="line"><span>	 * bit [15:14]: 00 默认下拉</span></span>
<span class="line"><span>     * bit [13]: 0 kepper功能</span></span>
<span class="line"><span>     * bit [12]: 1 pull/keeper使能</span></span>
<span class="line"><span>     * bit [11]: 0 关闭开路输出</span></span>
<span class="line"><span>     * bit [7:6]: 10 速度100Mhz</span></span>
<span class="line"><span>     * bit [5:3]: 110 R0/6驱动能力</span></span>
<span class="line"><span>     * bit [0]: 0 低转换率</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    ldr r0, =0X020E02F4	/*寄存器SW_PAD_GPIO1_IO03_BASE */</span></span>
<span class="line"><span>    ldr r1, =0X10B0</span></span>
<span class="line"><span>    str r1,[r0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>第 11~13 行：是设置 GPIO1_IO03 的配置寄存器，也就是寄存器 IOMUX_SW_PAD_CTL_PAD_GPIO1_IO03 的值，此寄存器地址为 0X020E02F4，代码里面已经给出了这个寄存器详细的位设置。</p><h4 id="_2-5-设置gpio功能" tabindex="-1">2.5 设置GPIO功能 <a class="header-anchor" href="#_2-5-设置gpio功能" aria-label="Permalink to &quot;2.5 设置GPIO功能&quot;">​</a></h4><p>接下来就是配置GPIO为输出功能</p><h5 id="_2-5-1-用哪个寄存器" tabindex="-1">2.5.1 用哪个寄存器？ <a class="header-anchor" href="#_2-5-1-用哪个寄存器" aria-label="Permalink to &quot;2.5.1 用哪个寄存器？&quot;">​</a></h5><p>这一次我们要用到GPIO外设模块的方向寄存器，我们找到参考手册的28.5.2 GPIO direction register (GPIOx_GDIR) ：</p><p><img src="`+I+'" alt="image-20260114152041922"></p><p>可以看到每一位控制一个GPIO引脚的方向，配置1为输出，0为输入，我们这里是GPIO1_IO03，所以这里就要配置GPIO[3]这一位为1。</p><h5 id="_2-5-2-寄存器地址" tabindex="-1">2.5.2 寄存器地址？ <a class="header-anchor" href="#_2-5-2-寄存器地址" aria-label="Permalink to &quot;2.5.2 寄存器地址？&quot;">​</a></h5><p>那这个寄存器地址是什么？我们先看这里28.5.2 GPIO direction register (GPIOx_GDIR) ：</p><p><img src="'+O+'" alt="image-20260114152109674"></p><p>发现是Base + 4h，那么这个Base是什么？这个应该是GPIO外设的基地址，我们可以直接看28.5 GPIO Memory Map/Register Definition ：</p><p><img src="'+a+'" alt="image-20260114152143146"></p><p>可以看到绝对地址是209_C004。那么基地址的话，应该是209_C000，我们来看一下存储器映像Chapter 2Memory Maps 这节的Table 2-2. AIPS-1 memory map (continued) ：</p><p><img src="'+P+`" alt="image-20260114152320222"></p><p>会发现GPIO1相关寄存器的基地址就是209_C000。</p><h5 id="_2-5-3-代码分析" tabindex="-1">2.5.3 代码分析 <a class="header-anchor" href="#_2-5-3-代码分析" aria-label="Permalink to &quot;2.5.3 代码分析&quot;">​</a></h5><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>	ldr r0, =0X0209C004	/*寄存器GPIO1_GDIR */</span></span>
<span class="line"><span>    ldr r1, =0X0000008		</span></span>
<span class="line"><span>    str r1,[r0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>第 1~3 行：是设置 GPIO 功能，经过上面几步操作， GPIO1_IO03 这个 IO 已经被配置为了GPIO 功能，所以还需要设置跟 GPIO 有关的寄存器。这几行是设置 GPIO1→GDIR 寄存器，将 GPIO1_IO03 设置为输出模式，也就是寄存器的 GPIO1_GDIR 的 bit3 置 1。</p><h4 id="_2-6-设置gpio输出电平" tabindex="-1">2.6 设置GPIO输出电平 <a class="header-anchor" href="#_2-6-设置gpio输出电平" aria-label="Permalink to &quot;2.6 设置GPIO输出电平&quot;">​</a></h4><h5 id="_2-6-1-用哪个寄存器" tabindex="-1">2.6.1 用哪个寄存器？ <a class="header-anchor" href="#_2-6-1-用哪个寄存器" aria-label="Permalink to &quot;2.6.1 用哪个寄存器？&quot;">​</a></h5><p>前面说过了，这里要用数据寄存器28.5.1 GPIO data register (GPIOx_DR) ：</p><p><img src="`+v+'" alt="image-20260114152415634"></p><p>这里还是每一位控制一个引脚。</p><h5 id="_2-6-2-寄存器地址" tabindex="-1">2.6.2 寄存器地址？ <a class="header-anchor" href="#_2-6-2-寄存器地址" aria-label="Permalink to &quot;2.6.2 寄存器地址？&quot;">​</a></h5><p>和方向寄存器一样，我们直接看28.5 GPIO Memory Map/Register Definition ：</p><p><img src="'+a+`" alt="image-20260114152143146"></p><h5 id="_2-6-3-代码分析" tabindex="-1">2.6.3 代码分析 <a class="header-anchor" href="#_2-6-3-代码分析" aria-label="Permalink to &quot;2.6.3 代码分析&quot;">​</a></h5><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>	ldr r0, =0X0209C000	/*寄存器GPIO1_DR */</span></span>
<span class="line"><span>	ldr r1, =0		</span></span>
<span class="line"><span>	str r1,[r0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>第 1~3 行设置 GPIO1→DR 寄存器，也就是设置 GPIO1_IO03 的输出，我们要点亮开发板上的 LED0，那么 GPIO1_IO03 就必须输出低电平，所以这里设置 GPIO1_DR 寄存器为 0。</p><h4 id="_2-7-死循环" tabindex="-1">2.7 死循环 <a class="header-anchor" href="#_2-7-死循环" aria-label="Permalink to &quot;2.7 死循环&quot;">​</a></h4><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loop:</span></span>
<span class="line"><span>	b loop</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>通过 b 指令， CPU 重复不断的跳到 loop 函数执行，进入一个死循环。 防止程序不受控制，跑到位置的地方。</p><h2 id="四、编译程序" tabindex="-1">四、编译程序 <a class="header-anchor" href="#四、编译程序" aria-label="Permalink to &quot;四、编译程序&quot;">​</a></h2><h3 id="_1-arm-linux-gnueabihf-gcc-编译文件" tabindex="-1">1. arm-linux-gnueabihf-gcc 编译文件 <a class="header-anchor" href="#_1-arm-linux-gnueabihf-gcc-编译文件" aria-label="Permalink to &quot;1. arm-linux-gnueabihf-gcc 编译文件&quot;">​</a></h3><p>我们是要编译出在 ARM 开发板上运行的可执行文件，所以要使用我们安装的交叉编译器 arm-linux-gnueabihf-gcc 来编译。先将 led.s 编译为对应的.o 文件，在终端中输入如下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-linux-gnueabihf-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> led.s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> led.o</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>上述命令就是将 led.s 编译为 led.o，其中“-g”选项是产生调试信息， GDB 能够使用这些调试信息进行代码调试。“-c”选项是编译源文件，但是不链接。“-o”选项是指定编译产生的文件名字，这里我们指定 led.s 编译完成以后的文件名字为 led.o。执行上述命令以后就会编译生成一个 led.o 文件。</p><p>led.o 文件并不是我们可以下载到开发板中运行的文件，一个工程中所有的 C 文件和汇编文件都会编译生成一个对应的.o 文件，我们需要将这.o 文件链接起来组合成可执行文件。</p><h3 id="_2-arm-linux-gnueabihf-ld-链接文件" tabindex="-1">2. arm-linux-gnueabihf-ld 链接文件 <a class="header-anchor" href="#_2-arm-linux-gnueabihf-ld-链接文件" aria-label="Permalink to &quot;2. arm-linux-gnueabihf-ld 链接文件&quot;">​</a></h3><p>arm-linux-gnueabihf-ld 用来将众多的.o 文件链接到一个指定的链接位置。我们在学习SMT32 的时候基本就没有听过“链接”这个词，我们一般用 MDK 编写好代码，然后点击“编译”， MDK 或者 IAR 就会自动帮我们编译好整个工程，最后再点击“下载”就可以将代码下载到开发板中。 详细的内容这里就不再说了，之前学习STM32的时候详细的分析过。</p><p>我们要区分“存储地址”和“运行地址”这两个概念，“存储地址”就是可执行文件存储在哪里，可执行文件的存储地址可以随意选择。“运行地址”就是代码运行的时候所处的地址，这个我们在链接的时候就已经确定好了，代码要运行，那就必须处于运行地址处，否则代码肯定运行出错。比如 I.MX6U 支持 SD 卡、 EMMC、 NAND 启动，因此代码可以存储到 SD 卡、 EMMC 或者 NAND 中，但是要运行的话就必须将代码从 SD 卡、 EMMC 或者NAND 中拷贝到其运行地址(链接地址)处，“存储地址”和“运行地址”可以一样，比如STM32 的存储起始地址和运行起始地址都是 0X08000000。</p><p>因此我们现在需要做的就是确定一下点灯的汇编程序最终的可执行文件其运行起始地址，也就是链接地址。上电以后 I.MX6U 的内部 boot rom 程序会将可执行文件拷贝到链接地址处，这个链接地址可以在 I.MX6U 的内部 128KB RAM 中(0X900000~0X91FFFF)，也可以在外部的 DDR 中，DDR中链接起始地址为 0X87800000。我们可以看一下I.MX6ULL的存储器映像：</p><p><img src="`+G+'" alt="image-20260114152618584"></p><p>I.MX6U-ALPHA 开发板的 DDR 容量有两种： 512MB 和256MB，起始地址都为 0X80000000，只不过 512MB 的终止地址为 0X9FFFFFFF，而256MB 容量的终止地址为 0X8FFFFFFF。之所以选择 0X87800000 这个地址是因为后面要学习的 u-boot 其链接地址就是 0X87800000，这样我们统一使用 0X87800000 这个链接地址，不容易记混。</p><p>确定了链接地址以后就可以使用 arm-linux-gnueabihf-ld 来将前面编译出来的 led.o 文件链接到 0X87800000 这个地址，使用如下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-linux-gnueabihf-ld</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Ttext</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0X87800000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> led.o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> led.elf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>“ -Ttext ”就是指定链接地址，“-o”选项指定链接生成的 elf 文件名，这里我们命名为 led.elf。上述命令执行完以后就会在工程目录下多一个 led.elf 文件 ：</p><img src="'+F+'" alt="image-20241108000446239"><p>led.elf 文件也不是我们最终烧写到 SD 卡中的可执行文件，我们要烧写镜像是使用的.bin 文件，因此还需要将 led.elf 文件转换为.bin 文件，这里我们就需要用到 arm-linux-gnueabihf-objcopy 这个工具了。</p><h3 id="_3-arm-linux-gnueabihf-objcopy-格式转换" tabindex="-1">3. arm-linux-gnueabihf-objcopy 格式转换 <a class="header-anchor" href="#_3-arm-linux-gnueabihf-objcopy-格式转换" aria-label="Permalink to &quot;3. arm-linux-gnueabihf-objcopy 格式转换&quot;">​</a></h3><p>arm-linux-gnueabihf-objcopy 更像一个格式转换工具，我们需要用它将 led.elf 文件转换为led.bin 文件，命令如下：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-linux-gnueabihf-objcopy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> binary</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> led.elf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> led.bin</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>“-O”选项指定以什么格式输出，后面的“binary”表示以二进制格式输出，选项“-S”表示不要复制源文件中的重定位信息和符号信息，“-g”表示不复制源文件中的调试信息。上述命令执行完成以后，就会生成一个bin文件：</p><img src="'+x+'" alt="image-20241108000520398"><p>这个.bin文件也不能直接放到开发板上运行， 这次是因为需要在.bin文件缺少启动相关信息。</p><h3 id="_4-arm-linux-gnueabihf-objdump-反汇编" tabindex="-1">4. arm-linux-gnueabihf-objdump 反汇编 <a class="header-anchor" href="#_4-arm-linux-gnueabihf-objdump-反汇编" aria-label="Permalink to &quot;4. arm-linux-gnueabihf-objdump 反汇编&quot;">​</a></h3><p>大多数情况下我们都是用 C 语言写程序的，有时候需要查看其汇编代码来调试代码，因此就需要进行反汇编，一般可以将 elf 文件反汇编，比如如下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-linux-gnueabihf-objdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> led.elf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> led.dis</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>“-D”选项表示反汇编所有的段，反汇编完成以后就会在当前目录下出现一个名为 led.dis 文件:</p><img src="'+f+'" alt="image-20241108000549113"><p>可以打开 led.dis 文件看一下，看看是不是汇编代码 :</p><img src="'+y+`" alt="image-20241108000654980"><p>可以看出 led.dis 里面是汇编代码，而且还可以看到内存分配情况。在0X87800000 处就是全局标号_start，也就是程序开始的地方。通过 led.dis 这个反汇编文件可以明显的看出我们的代码已经链接到了以 0X87800000 为起始地址的区域。</p><h3 id="_5-创建-makefile-文件" tabindex="-1">5. 创建 Makefile 文件 <a class="header-anchor" href="#_5-创建-makefile-文件" aria-label="Permalink to &quot;5. 创建 Makefile 文件&quot;">​</a></h3><p>前边那样一条一条太麻烦了，之前都学过makefile了，那刚好可以用啦。用“touch”命令在工程根目录下创建一个名为“Makefile”的文件，并添加以下内容：</p><div class="language-makefile vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">led.bin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:led.s</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	arm-linux-gnueabihf-gcc -g -c led.s -o led.o</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	arm-linux-gnueabihf-ld -Ttext 0X87800000 led.o -o led.elf</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	arm-linux-gnueabihf-objcopy -O binary -S -g led.elf led.bin</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	arm-linux-gnueabihf-objdump -D led.elf &gt; led.dis</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.PHONY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: clean</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	rm -rf *.o led.bin led.elf led.dis</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>之后我们直接一个make就可以完成编译啦。</p><h2 id="五、程序烧写" tabindex="-1">五、程序烧写 <a class="header-anchor" href="#五、程序烧写" aria-label="Permalink to &quot;五、程序烧写&quot;">​</a></h2><p>后边一小节再说。</p>`,155)])])}const S=n(M,[["render",X]]);export{B as __pageData,S as default};
